sys_script_include.script:
var AESPortalBootstrapUtil = Class.create();
AESPortalBootstrapUtil.prototype = {

    initialize: function() {
    },

    ensureTheme: function(themeSysId) {

        if (!themeSysId) {
            return false;
        }

        var includeId = this._getBootstrapInclude();

        if (!includeId) {
            return false;
        }

        return new global.AESPortalBootstrapGlobal().ensureThemeInclude(themeSysId, includeId);
    },

    _getBootstrapInclude: function() {

        var include = new GlideRecord('sp_js_include');
        include.addQuery('sys_id', 'd49af85793274bd0ef30f2918bba106a');
        include.setLimit(1);
        include.query();

        if (include.next()) {
            return include.getUniqueValue();
        }

        return '';
    },

    type: 'AESPortalBootstrapUtil'
};
